---@class UIMailCell
---@field RedImage                      	UnityEngine.RectTransform @是否已领取的状态
---@field AvailText                     	UnityEngine.UI.Text @有效期
---@field TitleText                     	UnityEngine.UI.Text @标题
---@field CellBGImage                   	Engine.UI.ImageAlterable @背景
local UIMailCell = Class('UIMailCell')

local LEFTSECONDFORMATTER = "HH:mm:ss"
local LEFTDAYFORMATTER = "dd"
local SevenDaysTime = 604800 -- 7 * 86400

local CHECK_COLOR = '#777777'
local UNCHECK_COLOR = '#FFFFFF'

function UIMailCell:__init()
    self.email = {}
    self.index = 0
    self.__countDownCB = nil
    ---@type fun(index:integer):void
    self.__clickCB = nil
    self.__isMyMail = false
    self.isChecked = false
    self.ImgFinish = nil
    self.tween = nil
    self.receiveEffect = nil
end

function UIMailCell:__delete()
    self.email = nil
    self.index = nil
    self.__clickCB = nil
    self.__isMyMail = false
    self.isChecked = nil
    self.ImgFinish = nil
    self.tween = nil
    self.receiveEffect = nil
end

function UIMailCell:Awake()
    self.ImgFinish = self.CellBGImage.transform.parent:Find("ImgFinish")
    self.receiveEffect = self.controller.transform:Find("UIFX_ImgReceive")
    KTool.SetActive(self.CellBGImage.gameObject, false)
end

function UIMailCell:Start()
    --local button = self.CellBGImage:GetComponent(typeof(Button))
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function(pointData)
        --邮箱格子点的事件处理
        if not isTable(self.email) then
            return
        end
        self:FreshCell(self.email, self.index, self.__isMyMail)
        self:SetSelected(self.isChecked)
        if self.__clickCB then
            self.__clickCB(self.index)
        end
    end

    self.__countDownCB = Events.AddListener(Constants.EventNames.UIMailCountDownEventName, Bind(self, self.CountAction))
end

---CountAction
---倒计时统计函数
---@param deltaTime number 倒计时经过的时间可能会大于1
function UIMailCell:CountAction(deltaTime)
    if not KTool.IsActive(self.controller.gameObject) then
        return
    end
    if not isTable(self.email) then
        return
    end
    if self.__isMyMail then
        return
    end
    if not self.__isMyMail then
        --local color = CHECK_COLOR
        --if not self.isChecked then
        --    color = UNCHECK_COLOR
        --end
        local expirationTime = checkNumber(self.email.expirationTime)
        --self.email.expirationTime = expirationTime
        --printInfo("expirationTime" .. self.email.expirationTime)
        if expirationTime > 86400 then
            --TimeSpan ts = TimeSpan.FromSeconds(expirationTime);

            local text = math.floor(expirationTime / 86400)--TimeUtils.GetDateTimeByUtcSeconds(expirationTime):ToString(LEFTDAYFORMATTER)
            local avaDays = tostring(text)
            self.AvailText.text = localize("有效期：_date_天", {_date_ = avaDays})
        else
            local text = TimeUtils.GetDateTimeByUtcSeconds(expirationTime):ToString(LEFTSECONDFORMATTER)
            self.AvailText.text = localize("有效期：_date_", {_date_ = text})
        end

    end
end

---SetClickCB
---设置邮箱列表单元格回调
---@param cb fun(index:integer):void @ 设置邮箱列表单元格回调
function UIMailCell:SetClickCB(cb)
    self.__clickCB = cb
end

function UIMailCell:SetSelected(checked)
    self.isChecked = checkBool(checked)
    KTool.SetActive(self.CellBGImage.gameObject, checkBool(checked))
    local hasDrawn = checkInt(self.email.hasDrawn)
    CfUtils.SetUISwitchImage(self.CellBGImage,  (self.isChecked and checkNumber(self.email.important) == 1 and hasDrawn == 0) and 2 or 1)
    --CfUtils.SetActive(self.ImgFinish, checkNumber(self.email.important) == 1 and hasDrawn and not self.isChecked)
    --if hasDrawn then
    --    CfUtils.SetUISwitchText(self.TitleText, (self.isChecked and checkNumber(self.email.important) == 1) and 1 or 2)
    --    CfUtils.SetUISwitchText(self.AvailText, (self.isChecked and checkNumber(self.email.important) == 1) and 1 or 2)
    --end
    if hasDrawn == 1 then
        if self.isChecked then
            CfUtils.SetUISwitchText(self.TitleText, 1)
            CfUtils.SetUISwitchText(self.AvailText, 1)
        else
            CfUtils.SetUISwitchText(self.TitleText, 2)
            CfUtils.SetUISwitchText(self.AvailText, 2)
        end
    end
    --if hasDrawn == 1 and checkNumber(self.email.important) == 0 then
    --    if checkBool(checked) then
    --        self.TitleText.color = XLuaUtils.HexToColor(CHECK_COLOR)
    --        self.AvailText.color = XLuaUtils.HexToColor(CHECK_COLOR)
    --    else
    --        self.TitleText.color = XLuaUtils.HexToColor(UNCHECK_COLOR)
    --        self.AvailText.color = XLuaUtils.HexToColor(UNCHECK_COLOR)
    --    end
    --end
end

---FreshCell
---刷新邮箱单元
---@param email table 邮箱返回的数据 {
---  title = string , hasDrawn,
---  content = string
---}
---@param index number 位置
---@param isMyMail boolean
function UIMailCell:FreshCell(email, index, isMyMail)
    if not isTable(email) then
        return
    end
    self.__isMyMail = isMyMail
    self.email = email
    self.index = index

    local canvasGroup = KTool.GetComponent(self.controller.gameObject, typeof(CanvasGroup))
    local hasDrawn = checkInt(self.email.hasDrawn)
    KTool.SetActive(self.RedImage.gameObject, hasDrawn == 0)
    KTool.SetActive(self.receiveEffect, hasDrawn == 0 and checkNumber(self.email.important) == 1)
    CfUtils.SetActive(self.ImgFinish, hasDrawn == 1 and checkNumber(self.email.important) == 1)
    CfUtils.SetUISwitchText(self.TitleText, (hasDrawn == 1 and checkNumber(self.email.important) == 1) and 2 or 1)
    CfUtils.SetUISwitchText(self.AvailText, (hasDrawn == 1 and checkNumber(self.email.important) == 1) and 2 or 1)
    local titleShadow = KTool.GetComponent(self.TitleText.gameObject, typeof(CS.UnityEngine.UI.Shadow))
    if titleShadow then
        titleShadow.enabled = checkNumber(self.email.important) == 1
    end
    local textShadow = KTool.GetComponent(self.AvailText.gameObject, typeof(CS.UnityEngine.UI.Shadow))
    if textShadow then
        textShadow.enabled = checkNumber(self.email.important) == 1
    end
    canvasGroup.alpha = 1
    if self.isChecked or hasDrawn == 0 then
        ---@type UnityEngine.UI.Image
        local image = KTool.GetComponent(self.RedImage.gameObject, typeof(CS.UnityEngine.UI.Image))
        local color = Color.New( 1,1,1, 1.0 );
        image.color = color
        if self.tween then
            self.tween:Kill(true)
            self.tween = nil
        end
        self.tween = image:DOFade(0.2, 1)
        self.tween:SetEase(Ease.InQuart):SetLoops(-1, LoopType.Yoyo)
    else
        ---已领取的状态
        --KTool.SetActive(self.RedImage.gameObject, false)
        --if checkNumber(self.email.important) == 0 and hasDrawn == 1 then
        --    ---普通邮件修改这个值,已领取的普通邮件
        --    canvasGroup.alpha = 0.2
        --end
    end
    --self.TitleText.text = string.format_color_tag(email.title, "#727272")
    self.TitleText.text = tostring(email.title)
    if not self.__isMyMail then
        self:CountAction(0)
    else
        self.AvailText.text = ''
    end
end

function UIMailCell:OnDestroy()
    if not isNull(self.__countDownCB) then
        Events.RemoveListener(Constants.EventNames.UIMailCountDownEventName, self.__countDownCB)
    end
    self.__countDownCB = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMailCell